import{_ as r,C as d,o as a,c as e,E as s,a1 as n}from"./chunks/framework.NjEjlYNI.js";const b=JSON.parse('{"title":"AI 难点速记卡","description":"考前 10 分钟冲刺 — 五大难点的记忆锚点/一句话类比/混淆点对照表","frontmatter":{"title":"AI 难点速记卡","description":"考前 10 分钟冲刺 — 五大难点的记忆锚点/一句话类比/混淆点对照表","difficulty":"intermediate","frequency":"high"},"headers":[],"relativePath":"ai-dev/cheat-sheet.md","filePath":"ai-dev/cheat-sheet.md"}'),l={name:"ai-dev/cheat-sheet.md"};function i(h,t,g,c,u,p){const o=d("DifficultyBadge");return a(),e("div",null,[s(o,{level:"intermediate"}),t[0]||(t[0]=n('<h1 id="🃏-ai-难点速记卡" tabindex="-1">🃏 AI 难点速记卡 <a class="header-anchor" href="#🃏-ai-难点速记卡" aria-label="Permalink to &quot;🃏 AI 难点速记卡&quot;">​</a></h1><h2 id="一句话解释" tabindex="-1">一句话解释 <a class="header-anchor" href="#一句话解释" aria-label="Permalink to &quot;一句话解释&quot;">​</a></h2><p>这是全模块最难 5 个主题的<strong>考前速记卡</strong>——每个主题浓缩成&quot;一句话类比 + 记忆锚点 + 高频混淆点&quot;，<strong>适合面试前 10 分钟快速过一遍</strong>，把抽象概念重新唤醒。</p><div class="tip custom-block"><p class="custom-block-title">💡 使用建议</p><p>先通读各章完整内容理解原理，考前再看本页复习。<strong>类比是记忆的钩子，不是知识的全部</strong>——理解还得回原文。</p></div><hr><h2 id="🀄-1-llm-核心原理" tabindex="-1">🀄 1. LLM 核心原理 <a class="header-anchor" href="#🀄-1-llm-核心原理" aria-label="Permalink to &quot;🀄 1. LLM 核心原理&quot;">​</a></h2><div class="analogy-card"><span class="analogy-title">🧩 一句话类比</span><div class="analogy-body"><strong>&quot;模型不是查数据库，是掷骰子&quot;</strong> —— 它生成&quot;最像答案&quot;的文字，不是&quot;查证过&quot;的事实。 </div></div><p><strong>记忆锚点：</strong></p><table tabindex="0"><thead><tr><th>概念</th><th>记忆锚点</th><th>高频混淆点</th></tr></thead><tbody><tr><td><strong>Token 化</strong></td><td>给文本&quot;切麻将牌&quot;</td><td>中文信息密度高 ≠ 便宜，汉字更稀疏更贵</td></tr><tr><td><strong>上下文窗口</strong></td><td>只有&quot;10 张便利贴&quot;</td><td>新内容不是&quot;覆盖&quot;旧的，而是&quot;挤掉&quot;最老的</td></tr><tr><td><strong>采样不稳定</strong></td><td>掷骰子（temperature=手劲）</td><td>temperature 调大 ≠ 更聪明，是更发散</td></tr><tr><td><strong>幻觉</strong></td><td>爱面子的&quot;民间专家&quot;</td><td>幻觉不是 bug，是训练目标（生成像样文字）的副作用</td></tr><tr><td><strong>结构化输出</strong></td><td>作文 / 填表格 / 填申请表</td><td>JSON Mode 保格式，不保内容正确</td></tr></tbody></table><p><strong>面试急救话术：</strong></p><blockquote><p>&quot;让 AI 输出稳定四板斧：降 temperature → 固定 seed → 结构化输出约束 → prompt 给 Few-shot 示例。&quot;</p></blockquote><hr><h2 id="🔧-2-ai-应用前端开发-流式" tabindex="-1">🔧 2. AI 应用前端开发（流式） <a class="header-anchor" href="#🔧-2-ai-应用前端开发-流式" aria-label="Permalink to &quot;🔧 2. AI 应用前端开发（流式）&quot;">​</a></h2><div class="analogy-card"><span class="analogy-title">🧩 一句话类比</span><div class="analogy-body"><strong>&quot;SSE 是水龙头（单向放水），WebSocket 是对讲机（双向喊话）&quot;</strong> —— Chat 默认选水龙头。 </div></div><p><strong>记忆锚点：</strong></p><table tabindex="0"><thead><tr><th>考点</th><th>记忆锚点</th><th>高频混淆点</th></tr></thead><tbody><tr><td><strong>流式解析</strong></td><td>拼贴&quot;撕碎的纸条&quot;</td><td>不能 <code>res.json()</code>，必须 <code>getReader()</code> 流式读</td></tr><tr><td><strong>防乱码</strong></td><td><code>TextDecoder(..., { stream: true })</code></td><td>不加 <code>{stream:true}</code>，多字节字符被拆两包就乱码</td></tr><tr><td><strong>防拆条</strong></td><td>buffer 拼到完整 <code>\\n\\n</code> 才处理</td><td>最后一段不完整要留到下次，不能丢</td></tr><tr><td><strong>结束标志</strong></td><td><code>[DONE]</code> 哨兵</td><td>没读到 <code>[DONE]</code> 前不能认为生成结束</td></tr><tr><td><strong>取消</strong></td><td>AbortController</td><td>取消后要标记&quot;已中断&quot;，不能悄悄消失</td></tr></tbody></table><p><strong>面试急救话术：</strong></p><blockquote><p>&quot;流式解析三个边界：<strong>半字</strong>（多字节）、<strong>半条</strong>（跨 chunk 消息）、<strong>半程</strong>（生成一半取消）。全处理了就稳了。&quot;</p></blockquote><hr><h2 id="💬-3-ai-对话界面工程" tabindex="-1">💬 3. AI 对话界面工程 <a class="header-anchor" href="#💬-3-ai-对话界面工程" aria-label="Permalink to &quot;💬 3. AI 对话界面工程&quot;">​</a></h2><div class="analogy-card"><span class="analogy-title">🧩 一句话类比</span><div class="analogy-body"><strong>&quot;消息状态机=外卖订单状态，自动滚动=陪跑不是绑架，Markdown 防截断=厨师边炒边上菜&quot;</strong></div></div><p><strong>记忆锚点：</strong></p><table tabindex="0"><thead><tr><th>考点</th><th>记忆锚点</th><th>高频混淆点</th></tr></thead><tbody><tr><td><strong>五态状态机</strong></td><td>外卖：下单/配送中/已送达/取消/异常</td><td>中断 ≠ 错误，必须分开（重试逻辑依赖它）</td></tr><tr><td><strong>Markdown 防截断</strong></td><td>未闭合的 ``` 先&quot;补锅盖&quot;</td><td>等闭合再渲染会闪烁，补闭合更顺滑</td></tr><tr><td><strong>智能滚动</strong></td><td>陪跑：用户翻历史就停下</td><td>跟随是默认，不跟随是用户选择</td></tr><tr><td><strong>增量渲染</strong></td><td>增量追加 ≠ 全量覆盖</td><td>全量覆盖几千字会卡顿</td></tr></tbody></table><p><strong>面试急救话术：</strong></p><blockquote><p>&quot;用户感知的连续过程比绝对正确更重要——代码块中途闪成纯文本再变回来，比始终不渲染更难受。&quot;</p></blockquote><hr><h2 id="🔌-4-mcp-协议深度" tabindex="-1">🔌 4. MCP 协议深度 <a class="header-anchor" href="#🔌-4-mcp-协议深度" aria-label="Permalink to &quot;🔌 4. MCP 协议深度&quot;">​</a></h2><div class="analogy-card"><span class="analogy-title">🧩 一句话类比</span><div class="analogy-body"><strong>&quot;MCP 是人和工具（USB-C），Host=人、Client=手、Server=工具；工具会干活、资源能查书、提示词是模板&quot;</strong></div></div><p><strong>记忆锚点：</strong></p><table tabindex="0"><thead><tr><th>考点</th><th>记忆锚点</th><th>高频混淆点</th></tr></thead><tbody><tr><td><strong>三层架构</strong></td><td>人（Host）/ 手（Client）/ 工具（Server）</td><td>Client 长在 Host 这边，不是 Server 的一部分</td></tr><tr><td><strong>三类能力</strong></td><td>干活 / 查书 / 套模板</td><td>Tools 有副作用，Resources 只读</td></tr><tr><td><strong>两种传输</strong></td><td>stdio=本地进程，SSE=远程服务</td><td>浏览器端接 SSE Server 可能要网关桥接</td></tr><tr><td><strong>ACP 区别</strong></td><td>MCP=人和工具，ACP=人和人</td><td>两者不同层，共存不互斥</td></tr></tbody></table><p><strong>面试急救话术：</strong></p><blockquote><p>&quot;写 MCP Server 四步：建 McpServer → 注册 tool/resource → 连 transport → 启动。参数用 zod schema 校验。&quot;</p></blockquote><hr><h2 id="🛡️-5-前端-ai-安全" tabindex="-1">🛡️ 5. 前端 AI 安全 <a class="header-anchor" href="#🛡️-5-前端-ai-安全" aria-label="Permalink to &quot;🛡️ 5. 前端 AI 安全&quot;">​</a></h2><div class="analogy-card"><span class="analogy-title">🧩 一句话类比</span><div class="analogy-body"><strong>&quot;API Key=房门钥匙（不能给访客）；Prompt 注入=对海关使诈的走私客；AI 输出=陌生人包裹（先过安检）&quot;</strong></div></div><p><strong>记忆锚点：</strong></p><table tabindex="0"><thead><tr><th>考点</th><th>记忆锚点</th><th>高频混淆点</th></tr></thead><tbody><tr><td><strong>Key 保护</strong></td><td>前台发临时门禁卡，钥匙留酒店</td><td>环境变量对前端可访问 ≠ 安全</td></tr><tr><td><strong>Prompt 注入</strong></td><td>模型分不清指令和数据的来源</td><td>前端只能缓解，边界在服务端</td></tr><tr><td><strong>输出消毒</strong></td><td>AI 输出 = 用户输入 = 不可信</td><td>react-markdown 默认不开 rehypeRaw 才是安全姿势</td></tr><tr><td><strong>数据合规</strong></td><td>发送前脱敏 + 用户可删除</td><td>聊天记录也是数据资产</td></tr></tbody></table><p><strong>面试急救话术：</strong></p><blockquote><p>&quot;Prompt 注入纵深防御四层：输入检测 → 系统提示声明 → 高危操作独立校验 → 权限最小化。最终边界在服务端。&quot;</p></blockquote><hr><h2 id="🎯-一句话汇总-背这-6-句就够" tabindex="-1">🎯 一句话汇总（背这 6 句就够） <a class="header-anchor" href="#🎯-一句话汇总-背这-6-句就够" aria-label="Permalink to &quot;🎯 一句话汇总（背这 6 句就够）&quot;">​</a></h2><ol><li><strong>LLM</strong>：模型是掷骰子，不是查字典</li><li><strong>流式</strong>：SSE 是水龙头，解析要防&quot;半字半条半程&quot;</li><li><strong>Chat UI</strong>：状态机是外卖单，滚动是陪跑</li><li><strong>MCP</strong>：人-手-工具，干活-查书-套模板</li><li><strong>安全</strong>：钥匙不出门，输出过安检，指令分来源</li><li><strong>通用</strong>：类比是钩子，理解回原文</li></ol><h2 id="关联知识" tabindex="-1">关联知识 <a class="header-anchor" href="#关联知识" aria-label="Permalink to &quot;关联知识&quot;">​</a></h2><ul><li><a href="./llm-basics.html">LLM 核心原理</a> — 第 1 卡完整版</li><li><a href="./ai-app-frontend.html">AI 应用前端开发</a> — 第 2 卡完整版</li><li><a href="./ai-chat-ui.html">AI 对话界面工程</a> — 第 3 卡完整版</li><li><a href="./mcp-protocol.html">MCP 协议深度</a> — 第 4 卡完整版</li><li><a href="./ai-security.html">前端 AI 安全</a> — 第 5 卡完整版</li></ul>',44))])}const m=r(l,[["render",i]]);export{b as __pageData,m as default};
